// Each new Poller without stop — interval + closure retained

function createLRU(max) {
  const map = new Map();
  return {
    get(k) { return map.get(k); },
    set(k, v) {
      if (map.size >= max) map.delete(map.keys().next().value);
      map.set(k, v);
    },
  };
}
const userCache = createLRU(500);

